#!/bin/bash
# meisai-checker Mac アプリ インストーラー
# 使い方: bash install_mac_app.sh
set -e

echo "=== meisai-checker Mac アプリ インストーラー ==="

# uvx の確認
if ! command -v uvx &> /dev/null; then
    echo ""
    echo "[エラー] uv が見つかりません。"
    echo "以下のコマンドでインストールしてください:"
    echo "  curl -LsSf https://astral.sh/uv/install.sh | sh"
    exit 1
fi

APP_DIR="$HOME/Applications"
APP_PATH="$APP_DIR/meisai-checker.app"
ICONSET="$(mktemp -d)/meisai_checker.iconset"

mkdir -p "$APP_DIR"
mkdir -p "$APP_PATH/Contents/MacOS"
mkdir -p "$APP_PATH/Contents/Resources"
mkdir -p "$ICONSET"

# --- アイコン生成 ---
ICON_PNG="$(mktemp).png"
echo "" | base64 -d > "$ICON_PNG"

for size in 16 32 64 128 256 512; do
    sips -z $size $size "$ICON_PNG" --out "$ICONSET/icon_${size}x${size}.png" > /dev/null
    sips -z $((size*2)) $((size*2)) "$ICON_PNG" --out "$ICONSET/icon_${size}x${size}@2x.png" > /dev/null
done
iconutil -c icns "$ICONSET" -o "$APP_PATH/Contents/Resources/meisai_checker.icns"
rm "$ICON_PNG"

# --- Info.plist ---
cat > "$APP_PATH/Contents/Info.plist" << 'PLIST'
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>CFBundleExecutable</key>
    <string>meisai-checker</string>
    <key>CFBundleIconFile</key>
    <string>meisai_checker.icns</string>
    <key>CFBundleIdentifier</key>
    <string>com.aki0ka.meisai-checker</string>
    <key>CFBundleName</key>
    <string>meisai-checker</string>
    <key>CFBundleDisplayName</key>
    <string>meisai-checker</string>
    <key>CFBundlePackageType</key>
    <string>APPL</string>
    <key>CFBundleVersion</key>
    <string>1.0</string>
    <key>NSHighResolutionCapable</key>
    <true/>
</dict>
</plist>
PLIST

# --- 起動スクリプト ---
cat > "$APP_PATH/Contents/MacOS/meisai-checker" << 'LAUNCHER'
#!/bin/bash
export PATH="/usr/local/bin:/opt/homebrew/bin:$HOME/.local/bin:$PATH"

if ! command -v uvx &> /dev/null; then
    osascript -e 'display alert "meisai-checker" message "uvx が見つかりません。\n\nuv をインストールしてください:\ncurl -LsSf https://astral.sh/uv/install.sh | sh" as critical'
    exit 1
fi

exec uvx --from meisai-checker@latest meisai-checker-gui
LAUNCHER
chmod +x "$APP_PATH/Contents/MacOS/meisai-checker"

# Finder に登録
/System/Library/Frameworks/CoreServices.framework/Frameworks/LaunchServices.framework/Support/lsregister -f "$APP_PATH" 2>/dev/null || true

echo ""
echo "✓ $APP_PATH を作成しました"
echo ""
echo "【Dock への追加】"
echo "  Finder で「移動 → ホーム → Applications」を開き、"
echo "  meisai-checker.app を Dock にドラッグしてください。"
